from pathlib import Path
root=Path('/mnt/data/kayad_work/commercial')

# 1) service: centralize active listing count and assertion
p=root/'backend/services/dealerSubscription.service.js'
s=p.read_text()
s=s.replace('import { findById } from "../db/index.js";','import { findById } from "../db/index.js";\nimport Car from "../models/Car.js";')
s=s.replace('''  const { count: listingsUsed, error } = await sb\n    .from("cars").select("id", { count: "exact", head: true }).eq("dealer", dealerId);\n  if (error) throw error;\n\n  const used = listingsUsed || 0;''','''  // Listing capacity is a commercial entitlement over live inventory, not a\n  // historical count. Deleted and sold vehicles must not permanently consume\n  // a dealer's plan capacity. Keep this query in the entitlement service so\n  // every caller uses the same definition.\n  const used = await Car.countDocuments({\n    dealer: dealerId,\n    deletedAt: { $exists: false },\n    status: { $in: ["available", "pending"] },\n  });''')
s=s.replace('''    listingsRemaining: listingMax === 0 ? 0 : Math.max(0, listingMax - used),\n    unlimitedListings: usable && listingMax === 0,''','''    listingsRemaining: listingMax === 0 ? null : Math.max(0, listingMax - used),\n    unlimitedListings: usable && listingMax === 0,''')
s += '''\n\n/**\n * Authoritative pre-create commercial gate for dealer inventory.\n * Controllers should call this immediately before creating a new listing;\n * the database entitlement remains the source of truth for plan state.\n */\nexport async function assertDealerCanCreateListing(dealerId) {\n  const entitlement = await getDealerEntitlement(dealerId);\n  if (entitlement.status === "none") {\n    const error = new Error("An active dealer subscription is required to list vehicles.");\n    error.code = "SUBSCRIPTION_REQUIRED";\n    error.status = 402;\n    throw error;\n  }\n  if (entitlement.locked) {\n    const error = new Error("Dealer listings are currently locked. Contact platform support.");\n    error.code = "LISTINGS_LOCKED";\n    error.status = 403;\n    throw error;\n  }\n  if (entitlement.expiresAt && new Date(entitlement.expiresAt) <= new Date()) {\n    const error = new Error("Your dealer subscription has expired. Renew your plan to continue listing.");\n    error.code = "SUBSCRIPTION_EXPIRED";\n    error.status = 402;\n    throw error;\n  }\n  if (entitlement.listingMax > 0 && entitlement.listingsUsed >= entitlement.listingMax) {\n    const error = new Error(`You've reached your plan limit of ${entitlement.listingMax} listings. Upgrade to list more.`);\n    error.code = "LISTING_LIMIT_REACHED";\n    error.status = 402;\n    throw error;\n  }\n  return entitlement;\n}\n'''
p.write_text(s)

# 2) car controller: dealers must always use authoritative entitlement; freeMarket is individual-seller only.
p=root/'backend/controllers/carController.js'
s=p.read_text()
s=s.replace('import { getDealerEntitlement } from "../services/dealerSubscription.service.js";','import { getDealerEntitlement, assertDealerCanCreateListing } from "../services/dealerSubscription.service.js";')
old='''    const config = await PlatformConfig.findOne().lean();\n    const pkgs = config?.packages || [];\n    const pkg = pkgs.find((p) => p.id === seller.dealerPackage) || null;\n\n    // Monetisation master switch (admin-controlled, no code change to flip):\n    // free unless an admin has explicitly turned freeMarket OFF. Absent config\n    // (fresh DB) therefore means free — listings are unlimited and free.\n    const monetisationOff = config?.freeMarket !== false || config?.waivePayments === true;\n\n    const isDealer = seller.role === "dealer";\n    const isSeller = seller.role === "individual_seller";\n'''
new='''    const config = await PlatformConfig.findOne().lean();\n    const pkgs = config?.packages || [];\n    const isDealer = seller.role === "dealer";\n    const isSeller = seller.role === "individual_seller";\n\n    // The platform free-market switch applies only to private sellers.\n    // Dealer commercial access is always determined by the authoritative\n    // dealer_subscriptions entitlement service; a missing configuration must\n    // never accidentally turn dealer inventory into a free unlimited plan.\n    const monetisationOff = config?.freeMarket !== false || config?.waivePayments === true;\n'''
if old not in s: raise SystemExit('car old block not found')
s=s.replace(old,new)
old2='''    if (monetisationOff) {\n      // Free-for-all launch mode — allow the listing, still track count for analytics.\n      shouldIncrementListingCount = true;\n    } else if (isDealer) {\n      const entitlement = await getDealerEntitlement(req.user.id);\n\n      if (entitlement.status === "none") {\n        return res.status(402).json({\n          success: false,\n          message: "An active dealer subscription is required to list vehicles. Choose a plan and complete M-Pesa payment.",\n          code: "SUBSCRIPTION_REQUIRED",\n        });\n      }\n\n      if (entitlement.locked) {\n        return res.status(403).json({\n          success: false,\n          message: "Dealer listings are currently locked. Contact platform support.",\n          code: "LISTINGS_LOCKED",\n        });\n      }\n\n      if (entitlement.expiresAt && new Date(entitlement.expiresAt) <= new Date()) {\n        return res.status(402).json({\n          success: false,\n          message: "Your dealer subscription has expired. Renew your plan to continue listing.",\n          code: "SUBSCRIPTION_EXPIRED",\n        });\n      }\n\n      if (entitlement.listingMax > 0 && entitlement.listingsUsed >= entitlement.listingMax) {\n        return res.status(402).json({\n          success: false,\n          message: `You've reached your plan limit of ${entitlement.listingMax} listings. Upgrade to list more.`,\n          code: "LISTING_LIMIT_REACHED",\n        });\n      }\n\n      shouldIncrementListingCount = true;\n    }\n'''
new2='''    if (isDealer) {\n      // Dealer monetisation never bypasses the entitlement contract, even\n      // while the public/private-seller market switch is in free mode.\n      await assertDealerCanCreateListing(req.user.id);\n      shouldIncrementListingCount = true;\n    } else if (monetisationOff) {\n      // Free-market mode is intentionally limited to individual sellers.\n      shouldIncrementListingCount = true;\n    }\n'''
if old2 not in s: raise SystemExit('car gate block not found')
s=s.replace(old2,new2)
p.write_text(s)

# 3) subscription routes: mutation rate limiting + idempotency
p=root/'backend/routes/subscriptionRoutes.js'
s=p.read_text()
s=s.replace('import { validateQuery, subscriptionAdminQuerySchema } from "../middleware/validate.js";','import { validateQuery, subscriptionAdminQuerySchema } from "../middleware/validate.js";\nimport { createLimiter } from "../middleware/rateLimiter.js";\nimport { idempotencyCheck } from "../middleware/idempotency.js";')
s=s.replace('router.post("/upgrade", protect, asyncHandler(upgradeSubscription));','router.post("/upgrade", protect, createLimiter, idempotencyCheck, asyncHandler(upgradeSubscription));')
s=s.replace('router.post("/cancel", protect, asyncHandler(cancelSubscription));','router.post("/cancel", protect, createLimiter, idempotencyCheck, asyncHandler(cancelSubscription));')
s=s.replace('router.post("/reactivate", protect, asyncHandler(reactivateSubscription));','router.post("/reactivate", protect, createLimiter, idempotencyCheck, asyncHandler(reactivateSubscription));')
p.write_text(s)

# 4) migration: make admin grant supersede existing active; revoke must be explicit.
mig=root/'supabase/migrations/20260908060000_dealer_commercial_entitlement_hardening.sql'
mig.write_text('''-- KAYAD Dealer Commercial & Entitlement Hardening\n-- Closes remaining commercial drift between legacy user package fields,\n-- subscription history and dealer inventory enforcement.\n\n-- Keep dealer subscription history auditable while ensuring only one active\n-- entitlement exists. The existing partial unique index is retained.\nCREATE UNIQUE INDEX IF NOT EXISTS dealer_subscriptions_one_active_uq\n  ON public.dealer_subscriptions(dealer)\n  WHERE status = 'active';\n\n-- Admin grants are authoritative plan changes. Supersede an existing active\n-- entitlement before inserting the new one so the unique invariant cannot turn\n-- a legitimate admin plan change into a database error.\nCREATE OR REPLACE FUNCTION public.kayad_grant_dealer_subscription_atomic(\n  p_dealer uuid,\n  p_plan_id text,\n  p_duration_days integer DEFAULT 30,\n  p_reason text DEFAULT 'admin_grant'\n) RETURNS jsonb\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\nDECLARE\n  v_plan jsonb;\n  v_sub dealer_subscriptions%ROWTYPE;\n  v_expires timestamptz;\n  v_price numeric;\n  v_listing_max integer;\n  v_name text;\n  v_features jsonb;\nBEGIN\n  IF p_dealer IS NULL OR p_plan_id IS NULL THEN RAISE EXCEPTION 'Dealer and plan are required'; END IF;\n  IF p_duration_days < 1 OR p_duration_days > 3660 THEN RAISE EXCEPTION 'Invalid subscription duration'; END IF;\n\n  PERFORM pg_advisory_xact_lock(hashtext('dealer_subscription:' || p_dealer::text));\n\n  IF NOT EXISTS (SELECT 1 FROM users WHERE id = p_dealer AND role = 'dealer') THEN\n    RAISE EXCEPTION 'Dealer not found';\n  END IF;\n\n  SELECT value INTO v_plan\n  FROM platform_config pc, jsonb_array_elements(COALESCE(pc.packages, '[]'::jsonb)) value\n  WHERE value->>'id' = p_plan_id\n  LIMIT 1;\n  IF v_plan IS NULL THEN RAISE EXCEPTION 'Plan not found'; END IF;\n\n  v_name := COALESCE(v_plan->>'name', p_plan_id);\n  v_price := COALESCE((v_plan->>'price')::numeric, (v_plan->>'priceMonthly')::numeric, 0);\n  v_listing_max := COALESCE((v_plan->>'listingMax')::integer, 0);\n  v_features := COALESCE(v_plan->'features', '[]'::jsonb);\n  v_expires := now() + make_interval(days => p_duration_days);\n\n  UPDATE dealer_subscriptions\n  SET status = 'cancelled', updated_at = now(),\n      metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(\n        'supersededAt', now(), 'supersededReason', p_reason\n      )\n  WHERE dealer = p_dealer AND status = 'active';\n\n  INSERT INTO dealer_subscriptions(\n    dealer, plan_id, plan_name, amount, currency, listing_max, features,\n    starts_at, expires_at, status, metadata\n  ) VALUES (\n    p_dealer, p_plan_id, v_name, v_price, 'KES', v_listing_max, v_features,\n    now(), v_expires, 'active', jsonb_build_object('source', p_reason)\n  ) RETURNING * INTO v_sub;\n\n  UPDATE users SET\n    dealer_package = p_plan_id, package_listing_max = v_listing_max,\n    package_expires_at = v_expires, package_auto_renew = false,\n    subscription_status = 'active', package_features = v_features,\n    listings_locked = false, updated_at = now()\n  WHERE id = p_dealer;\n\n  RETURN jsonb_build_object(\n    'id', v_sub.id, 'dealer', v_sub.dealer, 'planId', v_sub.plan_id,\n    'status', v_sub.status, 'expiresAt', v_sub.expires_at\n  );\nEND; $$;\n\nREVOKE ALL ON FUNCTION public.kayad_grant_dealer_subscription_atomic(uuid,text,integer,text) FROM PUBLIC;\n\n-- Revocation must be explicit: silently reporting success when no active\n-- entitlement existed made admin controls misleading and difficult to audit.\nCREATE OR REPLACE FUNCTION public.kayad_revoke_dealer_subscription_atomic(\n  p_dealer uuid, p_reason text DEFAULT 'admin_revoke'\n) RETURNS jsonb\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\nDECLARE\n  v_sub dealer_subscriptions%ROWTYPE;\nBEGIN\n  IF p_dealer IS NULL THEN RAISE EXCEPTION 'Dealer identity is required'; END IF;\n  PERFORM pg_advisory_xact_lock(hashtext('dealer_subscription:' || p_dealer::text));\n\n  UPDATE dealer_subscriptions\n  SET status = 'cancelled', updated_at = now(),\n      metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(\n        'revokedAt', now(), 'reason', p_reason\n      )\n  WHERE dealer = p_dealer AND status = 'active'\n  RETURNING * INTO v_sub;\n\n  IF NOT FOUND THEN RAISE EXCEPTION 'No active dealer subscription to revoke'; END IF;\n\n  UPDATE users SET\n    dealer_package = NULL, package_listing_max = 0, package_expires_at = NULL,\n    package_auto_renew = false, subscription_status = 'none',\n    package_features = '[]'::jsonb, updated_at = now()\n  WHERE id = p_dealer AND role = 'dealer';\n\n  RETURN jsonb_build_object(\n    'id', v_sub.id, 'dealer', p_dealer, 'planId', v_sub.plan_id, 'status', 'none'\n  );\nEND; $$;\n\nREVOKE ALL ON FUNCTION public.kayad_revoke_dealer_subscription_atomic(uuid,text) FROM PUBLIC;\n\nCOMMENT ON TABLE public.dealer_subscriptions IS\n  'Authoritative dealer commercial entitlement history. Legacy user package fields are compatibility projections only; dealer listing access is enforced from this table.';\n''')

# 5) Add a focused validation script.
val=root/'scripts/dealer-commercial-entitlement-hardening-validation.js'
val.write_text('''import fs from "node:fs";\nimport path from "node:path";\n\nconst root = process.cwd();\nconst read = (p) => fs.readFileSync(path.join(root, p), "utf8");\nconst checks = [\n  ["dealer entitlement service owns listing count", read("backend/services/dealerSubscription.service.js").includes("assertDealerCanCreateListing")],\n  ["deleted/sold inventory does not consume active capacity", read("backend/services/dealerSubscription.service.js").includes('status: { $in: ["available", "pending"] }')],\n  ["dealer listing path cannot use free-market bypass", !read("backend/controllers/carController.js").includes('if (monetisationOff) {\\n      // Free-for-all launch mode')],\n  ["subscription mutations rate limited", read("backend/routes/subscriptionRoutes.js").includes("createLimiter")],\n  ["subscription mutations idempotent", read("backend/routes/subscriptionRoutes.js").includes("idempotencyCheck")],\n  ["admin grant supersedes active entitlement", read("supabase/migrations/20260908060000_dealer_commercial_entitlement_hardening.sql").includes("supersededReason")],\n  ["admin revoke fails when nothing is active", read("supabase/migrations/20260908060000_dealer_commercial_entitlement_hardening.sql").includes("No active dealer subscription to revoke")],\n  ["one active entitlement invariant", read("supabase/migrations/20260908060000_dealer_commercial_entitlement_hardening.sql").includes("dealer_subscriptions_one_active_uq")],\n];\nlet failed = 0;\nfor (const [name, ok] of checks) {\n  console.log(`${ok ? "PASS" : "FAIL"} - ${name}`);\n  if (!ok) failed++;\n}\nif (failed) process.exit(1);\nconsole.log(`Dealer commercial entitlement hardening: ${checks.length}/${checks.length} PASS`);\n''')
